(3586270, 502654, 63588, '<td valign="top">A tad too dark and I''d prefer it a bit crisper on the edges of the bubble. I like the blue-green tone.</td>', 'A tad too dark and I''d prefer it a bit crisper on the edges of the bubble. I like the blue-green tone.', '2007-04-26 20:01:40.000000', NULL, 1),
(3586277, 502547, 34059, '<td valign="top">This is my favorite of the challenge! Everything works well in this picture, I like the composition, the light, even the border (which usually I don''t like). Very good job, I hope it scores well, good luck!</td>', 'This is my favorite of the challenge! Everything works well in this picture, I like the composition, the light, even the border (which usually I don''t like). Very good job, I hope it scores well, good luck!', '2007-04-26 20:03:55.000000', NULL, 1),
