(3591409, 502630, 30049, '<td valign="top">I hope this makes the front page.  Adorable expression captured in the cats face.  You did a nice job of getting the cat and the bubble in the same focal plane to eliminate the bg via DOF.  Good luck in the challenge.</td>', 'I hope this makes the front page.  Adorable expression captured in the cats face.  You did a nice job of getting the cat and the bubble in the same focal plane to eliminate the bg via DOF.  Good luck in the challenge.', '2007-04-29 00:22:07.000000', NULL, 1),
(3591418, 501560, 37623, '<td valign="top">this is so cool...i see a man bent over, arm raised behind him, ready to jump...great!</td>', 'this is so cool...i see a man bent over, arm raised behind him, ready to jump...great!', '2007-04-29 00:25:50.000000', NULL, 1),
(3591425, 502572, 37623, '<td valign="top">very very nice.  one of my favorites in this challenge.</td>', 'very very nice.  one of my favorites in this challenge.', '2007-04-29 00:27:53.000000', NULL, 1),
(3591436, 502011, 37623, '<td valign="top">almost like a fantasy-land photo...dreams are alive inside the bubble as it gets gently caressed and passed along by flowery fingers...</td>', 'almost like a fantasy-land photo...dreams are alive inside the bubble as it gets gently caressed and passed along by flowery fingers...', '2007-04-29 00:31:45.000000', NULL, 1),
