(3591783, 501456, 23478, '<td valign="top">Cute photo, maybe crop off the left part of the photo to focus more on Alex and the bubbles.</td>', 'Cute photo, maybe crop off the left part of the photo to focus more on Alex and the bubbles.', '2007-04-29 04:17:02.000000', NULL, 1),
(3591786, 500772, 23478, '<td valign="top">Nice image, the colors seem a bit off though.</td>', 'Nice image, the colors seem a bit off though.', '2007-04-29 04:17:24.000000', NULL, 1),
