(3591788, 502343, 23478, '<td valign="top">Cute!  I smiled as  a DIYer.  The shallow DOF is great.</td>', 'Cute!  I smiled as  a DIYer.  The shallow DOF is great.', '2007-04-29 04:18:30.000000', NULL, 1),
(3591789, 500505, 23478, '<td valign="top">Kind of abstract - The red hue makes the subject blend in a bit too much with the background.</td>', 'Kind of abstract - The red hue makes the subject blend in a bit too much with the background.', '2007-04-29 04:19:24.000000', NULL, 1),
(3591790, 502400, 23478, '<td valign="top">Nice candid moment!</td>', 'Nice candid moment!', '2007-04-29 04:19:44.000000', NULL, 1),
