(3591792, 501969, 23478, '<td valign="top">kind of abstract, kind of different, kind of ... ok, what is that guy doing anyhow?!?</td>', 'kind of abstract, kind of different, kind of ... ok, what is that guy doing anyhow?!?', '2007-04-29 04:21:11.000000', NULL, 1),
(3591793, 500824, 23478, '<td valign="top">Interesting, but very abstract.</td>', 'Interesting, but very abstract.', '2007-04-29 04:21:55.000000', NULL, 1),
(3591795, 502311, 23478, '<td valign="top">They are bubbles, but there is nothing to really grab and focus the attention in this image.</td>', 'They are bubbles, but there is nothing to really grab and focus the attention in this image.', '2007-04-29 04:25:13.000000', NULL, 1),
