(3591797, 502645, 23478, '<td valign="top">A bit too blurry.</td>', 'A bit too blurry.', '2007-04-29 04:26:03.000000', NULL, 1),
(3591798, 502590, 23478, '<td valign="top">fun image, just a tad over exposed.</td>', 'fun image, just a tad over exposed.', '2007-04-29 04:26:31.000000', NULL, 1),
(3591799, 502017, 23478, '<td valign="top">Nice idea, but the background is in focus and the subject is not.</td>', 'Nice idea, but the background is in focus and the subject is not.', '2007-04-29 04:27:00.000000', NULL, 1),
(3591801, 501300, 23478, '<td valign="top">A dark background and take out some of the grain, and this would be an excellent image.</td>', 'A dark background and take out some of the grain, and this would be an excellent image.', '2007-04-29 04:27:36.000000', NULL, 1),
(3591802, 501415, 23478, '<td valign="top">Mr woody is handy with pretty much anything!  Nicely done.</td>', 'Mr woody is handy with pretty much anything!  Nicely done.', '2007-04-29 04:29:03.000000', NULL, 1),
(3591803, 500731, 23478, '<td valign="top">Nice image.</td>', 'Nice image.', '2007-04-29 04:29:18.000000', NULL, 1),
(3591804, 501874, 23478, '<td valign="top">Nice surreal feel.</td>', 'Nice surreal feel.', '2007-04-29 04:29:32.000000', NULL, 1),
(3591806, 501593, 23478, '<td valign="top">Nice, abstract feel.</td>', 'Nice, abstract feel.', '2007-04-29 04:30:43.000000', NULL, 1),
(3591807, 501620, 23478, '<td valign="top">Nicely done, I like the framing.</td>', 'Nicely done, I like the framing.', '2007-04-29 04:31:02.000000', NULL, 1),
(3591808, 501454, 23478, '<td valign="top">Nice color, the centered composition works well for this type of image.</td>', 'Nice color, the centered composition works well for this type of image.', '2007-04-29 04:35:16.000000', NULL, 1),
(3591809, 501714, 23478, '<td valign="top">Nice portrait and excellent feel... I think a smiling Barbie might blend with the bubbles better, but that is just my opinion.</td>', 'Nice portrait and excellent feel... I think a smiling Barbie might blend with the bubbles better, but that is just my opinion.', '2007-04-29 04:37:49.000000', NULL, 1),
(3591811, 502555, 23478, '<td valign="top">well composed.</td>', 'well composed.', '2007-04-29 04:40:21.000000', NULL, 1),
(3591812, 502688, 23478, '<td valign="top">soft focus and the fact that the bubbles blend in a bit too much with the background are the only downsides here. nicely done.</td>', 'soft focus and the fact that the bubbles blend in a bit too much with the background are the only downsides here. nicely done.', '2007-04-29 04:41:25.000000', NULL, 1),
(3591813, 500437, 23478, '<td valign="top">Interesting, I like the contrast in colors.</td>', 'Interesting, I like the contrast in colors.', '2007-04-29 04:41:54.000000', NULL, 1),
(3591814, 501830, 23478, '<td valign="top">wonderful idea and nicely executed.</td>', 'wonderful idea and nicely executed.', '2007-04-29 04:43:03.000000', NULL, 1),
(3591961, 501137, 67152, '<td valign="top">i like the perspective and colors a great deal but the grain likely caused you troubles with the voters - 7</td>', 'i like the perspective and colors a great deal but the grain likely caused you troubles with the voters - 7', '2007-04-29 09:43:35.000000', NULL, 1),
(3591964, 501300, 67152, '<td valign="top">i like the concept a lot but there is a lot of graininess/ pixelation that is really unfortunate in macro images</td>', 'i like the concept a lot but there is a lot of graininess/ pixelation that is really unfortunate in macro images', '2007-04-29 09:45:21.000000', NULL, 1),
(3591970, 501335, 67152, '<td valign="top">lovely colors and shapes - would have liked it a little better if it were a little sharper in focus</td>', 'lovely colors and shapes - would have liked it a little better if it were a little sharper in focus', '2007-04-29 09:50:51.000000', NULL, 1),
(3592010, 501978, 50695, '<td valign="top">I don''t know the magic that makes this a 10. It must have something to do with the green of the water, the veil of tears, a surfer distinguished only by the point of his board, but there you have it... a 10... the world in a photo, the universe in stained glass.</td>', 'I don''t know the magic that makes this a 10. It must have something to do with the green of the water, the veil of tears, a surfer distinguished only by the point of his board, but there you have it... a 10... the world in a photo, the universe in stained glass.', '2007-04-29 10:19:52.000000', NULL, 1),
(3592014, 500423, 50695, '<td valign="top">You''ve used bubbles to make a picture of a person look like a picture of a picture... a picture of a beautiful, mysterious picture. a picture of a picture from my own past, my own mystery. a picture of a picture whose ghostly energy was discovered by your picture of it, an orb of energy appearing right between her eyes, as though her soul were focused there. This sort of ecstatic, dangerous dance can only get a 10.</td>', 'You''ve used bubbles to make a picture of a person look like a picture of a picture... a picture of a beautiful, mysterious picture. a picture of a picture from my own past, my own mystery. a picture of a picture whose ghostly energy was discovered by your picture of it, an orb of energy appearing right between her eyes, as though her soul were focused there. This sort of ecstatic, dangerous dance can only get a 10.', '2007-04-29 10:23:33.000000', NULL, 1),
(3592017, 502381, 50695, '<td valign="top">not just any pop, 70''s bubblegum pop! the interaction here, the implied story, is just so visual, so... photographic! And I love the obscured but clear expression on the popped one''s face, unphased by explosion. 9</td>', 'not just any pop, 70''s bubblegum pop! the interaction here, the implied story, is just so visual, so... photographic! And I love the obscured but clear expression on the popped one''s face, unphased by explosion. 9', '2007-04-29 10:26:10.000000', NULL, 1),
(3592018, 500637, 50695, '<td valign="top">I love the doubling here, and the random squiggles. My kind of picture. 9</td>', 'I love the doubling here, and the random squiggles. My kind of picture. 9', '2007-04-29 10:26:53.000000', NULL, 1),
(3592019, 502471, 50695, '<td valign="top">I love the sheer mass and power of the foam in this composition. 8</td>', 'I love the sheer mass and power of the foam in this composition. 8', '2007-04-29 10:27:21.000000', NULL, 1),
(3592020, 502542, 50695, '<td valign="top">a window to another world... 8</td>', 'a window to another world... 8', '2007-04-29 10:27:44.000000', NULL, 1),
(3592022, 501850, 50695, '<td valign="top">action occurring in obscurity, covered with glimmer... it''s like Shakespeare! 9</td>', 'action occurring in obscurity, covered with glimmer... it''s like Shakespeare! 9', '2007-04-29 10:28:31.000000', NULL, 1),
(3592023, 502631, 50695, '<td valign="top">I like the simple composition, and the way the two circles change their relationship once you realize what they are. 8</td>', 'I like the simple composition, and the way the two circles change their relationship once you realize what they are. 8', '2007-04-29 10:29:14.000000', NULL, 1),
(3592024, 502400, 50695, '<td valign="top">a perfect capture. 9</td>', 'a perfect capture. 9', '2007-04-29 10:29:30.000000', NULL, 1),
(3592032, 499812, 50695, '<td valign="top">it looks like sadness but it''s actually concentration, absorption. it''s not the grieving of a loss, but an actual loss... a loss of self into another world. There''s something so classical about this... the pose with the foreshortened arm and the slightly downturned face, the angle of her sword... I mean pinwheel... the divine triad of bubbles. The crop seems to be fighting the classical quality of this but also accentuates it by getting so tight on it, like a detail of a classical painting to make some point about it: <i>Notice the perfect triangle created by St. Catherine''s sword... I mean wheel... and its perfect mirroring by the triangle of angels that appear over her left eye. She peers down upon humanity with a blessing but also with pity...</i> <br/> <br/>oh, and the kid is adorable. 10</td>', 'it looks like sadness but it''s actually concentration, absorption. it''s not the grieving of a loss, but an actual loss... a loss of self into another world. There''s something so classical about this... the pose with the foreshortened arm and the slightly downturned face, the angle of her sword... I mean pinwheel... the divine triad of bubbles. The crop seems to be fighting the classical quality of this but also accentuates it by getting so tight on it, like a detail of a classical painting to make some point about it: Notice the perfect triangle created by St. Catherine''s sword... I mean wheel... and its perfect mirroring by the triangle of angels that appear over her left eye. She peers down upon humanity with a blessing but also with pity...  oh, and the kid is adorable. 10', '2007-04-29 10:35:49.000000', NULL, 1),
(3592034, 501874, 50695, '<td valign="top">dazzling pop art. 9</td>', 'dazzling pop art. 9', '2007-04-29 10:36:42.000000', NULL, 1),
(3592035, 500759, 50695, '<td valign="top">very compelling concept. 7</td>', 'very compelling concept. 7', '2007-04-29 10:37:12.000000', NULL, 1),
(3592038, 501254, 50695, '<td valign="top">I wish I could see the hat better. Otherwise, I love this. Nice use of the hand. Aren''t hands magnificent? This looks like snaffles, btw. 8</td>', 'I wish I could see the hat better. Otherwise, I love this. Nice use of the hand. Aren''t hands magnificent? This looks like snaffles, btw. 8', '2007-04-29 10:39:12.000000', NULL, 1),
(3592040, 500776, 50695, '<td valign="top">strange and unique. almost thought-provoking enough to be compelling. if I make myself look at it, though, it maintains my interest. I like that this has nothing to reward the first glance. It forces you to look twice. Gloriously non-DPC.  8</td>', 'strange and unique. almost thought-provoking enough to be compelling. if I make myself look at it, though, it maintains my interest. I like that this has nothing to reward the first glance. It forces you to look twice. Gloriously non-DPC.  8', '2007-04-29 10:41:26.000000', NULL, 1),
(3592042, 502694, 50695, '<td valign="top">this would look great in black-and-white... I love how painterly it looks.</td>', 'this would look great in black-and-white... I love how painterly it looks.', '2007-04-29 10:42:47.000000', NULL, 1),
(3592043, 502664, 50695, '<td valign="top">unrelentingly odd. 7</td>', 'unrelentingly odd. 7', '2007-04-29 10:43:08.000000', NULL, 1),
(3592044, 501857, 50695, '<td valign="top">great abstract patterns. 7</td>', 'great abstract patterns. 7', '2007-04-29 10:43:36.000000', NULL, 1),
(3592046, 501010, 50695, '<td valign="top">I hope this ribbons. 9</td>', 'I hope this ribbons. 9', '2007-04-29 10:44:40.000000', NULL, 1),
(3592049, 501871, 50695, '<td valign="top">love his expression and the way the lines of perspective seem to be damning him to some fecal dimension of hell. this might have been easier for me to take in black and white. 7</td>', 'love his expression and the way the lines of perspective seem to be damning him to some fecal dimension of hell. this might have been easier for me to take in black and white. 7', '2007-04-29 10:46:11.000000', NULL, 1),
(3592054, 502485, 50695, '<td valign="top">I find this charming and nostalgic, like I am entering a child''s world instead of merely seeing a photo of a child. 8</td>', 'I find this charming and nostalgic, like I am entering a child''s world instead of merely seeing a photo of a child. 8', '2007-04-29 10:47:35.000000', NULL, 1),
(3592056, 502632, 50695, '<td valign="top">nice composition, I like the mount of darkness and the almost invisible gyrations of the bubble, and the raised sword of bubblemaking. 7</td>', 'nice composition, I like the mount of darkness and the almost invisible gyrations of the bubble, and the raised sword of bubblemaking. 7', '2007-04-29 10:48:25.000000', NULL, 1),
(3592058, 500104, 50695, '<td valign="top">I love that temporarily-defeated-but-I-WILL-get-revenge expresion. Nice composition, too, having her "cornered" by the bubbles. The foreground elements put her in a 3-dimensional corner. Well done. 9</td>', 'I love that temporarily-defeated-but-I-WILL-get-revenge expresion. Nice composition, too, having her "cornered" by the bubbles. The foreground elements put her in a 3-dimensional corner. Well done. 9', '2007-04-29 10:49:58.000000', NULL, 1),
(3592063, 501975, 50695, '<td valign="top">A palpable sense of joy. this seems like the highest possible energy for joy. Too much energy and it either becomes painful or turns into peaceful bliss. 10</td>', 'A palpable sense of joy. this seems like the highest possible energy for joy. Too much energy and it either becomes painful or turns into peaceful bliss. 10', '2007-04-29 10:52:02.000000', NULL, 1),
(3592065, 501917, 67152, '<td valign="top">Really nice photo - too bad about the hot spots above the main bubble - note that these can be removed in basic editing.</td>', 'Really nice photo - too bad about the hot spots above the main bubble - note that these can be removed in basic editing.', '2007-04-29 10:52:36.000000', NULL, 1),
(3592066, 502452, 50695, '<td valign="top">a unique angle on the situation. 8</td>', 'a unique angle on the situation. 8', '2007-04-29 10:52:42.000000', NULL, 1),
(3592070, 501643, 50695, '<td valign="top">nice little allegory. I don''t normally give high scores to ladybugs, but I am always willing to make exceptions. 8</td>', 'nice little allegory. I don''t normally give high scores to ladybugs, but I am always willing to make exceptions. 8', '2007-04-29 10:53:20.000000', NULL, 1),
