INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3594951, 502630, 51597, '<td valign="top">The best...resembles my kitty.. <br/>I just love your picture.</td>', 'The best...resembles my kitty.. I just love your picture.', '2007-04-30 08:25:12.000000', NULL, 1),
(3595038, 501975, 38032, '<td valign="top">Excellent subject, light and colors.  the only thing that might make stronger would be a slightly more offset subject (slightly to the right in the frame) and if the horizon appeared either level or even more exaggerately not level. 7</td>', 'Excellent subject, light and colors.  the only thing that might make stronger would be a slightly more offset subject (slightly to the right in the frame) and if the horizon appeared either level or even more exaggerately not level. 7', '2007-04-30 08:54:21.000000', NULL, 1),
(3595050, 502475, 38032, '<td valign="top">YES! - you have successfully done what I thought I had done but failed to do in the last bubble challenge (play with bubbles and bokeh - yours is a more obvious approach).  This is BEA-yootiful. 8</td>', 'YES! - you have successfully done what I thought I had done but failed to do in the last bubble challenge (play with bubbles and bokeh - yours is a more obvious approach).  This is BEA-yootiful. 8', '2007-04-30 08:57:09.000000', NULL, 1),
(3595057, 502596, 38032, '<td valign="top">I think if Joe''s eyes and head-top were the only thing showing while the rest of him was under water this would be more effective.</td>', 'I think if Joe''s eyes and head-top were the only thing showing while the rest of him was under water this would be more effective.', '2007-04-30 08:58:51.000000', NULL, 1),
(3595068, 501709, 38032, '<td valign="top">This is the type of image that could be mediocre or excellent - the rich contrast and saturated colors without distractions make this beautiful and simple. 8</td>', 'This is the type of image that could be mediocre or excellent - the rich contrast and saturated colors without distractions make this beautiful and simple. 8', '2007-04-30 09:00:13.000000', NULL, 1),
(3595073, 501375, 38032, '<td valign="top">The subject needs more attention here.</td>', 'The subject needs more attention here.', '2007-04-30 09:02:03.000000', NULL, 1),
(3595143, 502017, 72318, '<td valign="top">the focus is on the towel in the background... even if it was intentional it doesnt really fit.</td>', 'the focus is on the towel in the background... even if it was intentional it doesnt really fit.', '2007-04-30 09:31:33.000000', NULL, 1),
(3595163, 500061, 72318, '<td valign="top">I can see how the model might have wanted to keep the bra/bikini top on but it detracts from the realism, would have been much better served if it were a bubble bikini top - who wears clothes in the bath? Plus it is more playful. Also the face seems a bit blurred, which is never a good idea unless it is clearly intentional with the POV as well (and in this case it isnt), if you wanted to concentrate on the torso by using selective focus, why not crop the face out?</td>', 'I can see how the model might have wanted to keep the bra/bikini top on but it detracts from the realism, would have been much better served if it were a bubble bikini top - who wears clothes in the bath? Plus it is more playful. Also the face seems a bit blurred, which is never a good idea unless it is clearly intentional with the POV as well (and in this case it isnt), if you wanted to concentrate on the torso by using selective focus, why not crop the face out?', '2007-04-30 09:37:02.000000', NULL, 1),
(3595169, 502377, 72318, '<td valign="top">nice idea, maybe too high key for the hand? one of the better shots in this challenge :)</td>', 'nice idea, maybe too high key for the hand? one of the better shots in this challenge :)', '2007-04-30 09:39:03.000000', NULL, 1),
