(3599653, 502377, 3087, '<td valign="top">Nicely done.... love the clean background and simple composition. Lighting on the hand seems a bit harsh - would prefer it the tones/ lighting of the hand more closely matched those of the face. But I like it.</td>', 'Nicely done.... love the clean background and simple composition. Lighting on the hand seems a bit harsh - would prefer it the tones/ lighting of the hand more closely matched those of the face. But I like it.', '2007-05-01 12:44:16.000000', NULL, 1),
(3599657, 501957, 3087, '<td valign="top">Nice colour saturation, nice sharp detail, and strong composition. like the blues, greens and white.</td>', 'Nice colour saturation, nice sharp detail, and strong composition. like the blues, greens and white.', '2007-05-01 12:45:44.000000', NULL, 1),
(3599659, 502330, 3087, '<td valign="top">Lovely lighting and colours and I like the black background.</td>', 'Lovely lighting and colours and I like the black background.', '2007-05-01 12:46:14.000000', NULL, 1),
