(3602909, 500840, 61651, '<td valign="top">This is such a creative take on the challenge; you thought it up and shot it well.</td>', 'This is such a creative take on the challenge; you thought it up and shot it well.', '2007-05-01 22:42:50.000000', NULL, 1),
(3602917, 502514, 77886, '<td valign="top">It would be better if you cut off a little of the right side, because the dishes in the background are too distracting.</td>', 'It would be better if you cut off a little of the right side, because the dishes in the background are too distracting.', '2007-05-01 22:43:54.000000', NULL, 1),
